import { ChevronDown, ChevronUp, Settings2 } from "lucide-react";
import { useState } from "react";
import type { ScanDefaultsResponse, ScanOptionsPayload, ScanProfileId } from "../api/client";

interface DiscoveryScanOptionsProps {
  value: ScanOptionsPayload;
  onChange: (value: ScanOptionsPayload) => void;
  defaults: ScanDefaultsResponse | null;
  disabled?: boolean;
}

const PROFILE_ORDER: ScanProfileId[] = ["quick", "standard", "deep", "aggressive", "custom"];

function Toggle({
  label,
  hint,
  checked,
  onChange,
  disabled,
}: {
  label: string;
  hint?: string;
  checked: boolean;
  onChange: (v: boolean) => void;
  disabled?: boolean;
}) {
  return (
    <label className="sa-scan-opt-toggle">
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(e) => onChange(e.target.checked)} />
      <span>
        {label}
        {hint ? <small>{hint}</small> : null}
      </span>
    </label>
  );
}

function NumField({
  label,
  value,
  min,
  max,
  onChange,
  disabled,
}: {
  label: string;
  value: number | undefined;
  min: number;
  max: number;
  onChange: (v: number) => void;
  disabled?: boolean;
}) {
  return (
    <label className="sa-scan-opt-field">
      <span>{label}</span>
      <input
        className="sa-input"
        type="number"
        min={min}
        max={max}
        value={value ?? ""}
        disabled={disabled}
        onChange={(e) => onChange(Number(e.target.value))}
      />
    </label>
  );
}

export default function DiscoveryScanOptions({
  value,
  onChange,
  defaults,
  disabled = false,
}: DiscoveryScanOptionsProps) {
  const [advancedOpen, setAdvancedOpen] = useState(value.profile === "custom");

  const profiles = defaults?.profiles ?? [];
  const limits = defaults?.limits;
  const isCustom = value.profile === "custom";

  function patch(partial: Partial<ScanOptionsPayload>) {
    onChange({ ...value, ...partial });
  }

  function selectProfile(profile: ScanProfileId) {
    const meta = profiles.find((p) => p.id === profile);
    if (profile === "custom") {
      onChange({ ...value, profile: "custom" });
      setAdvancedOpen(true);
      return;
    }
    onChange({
      profile,
      scan_type: "syn",
      use_snmp: profile !== "quick",
      ...(meta?.defaults as Partial<ScanOptionsPayload>),
    });
    setAdvancedOpen(false);
  }

  return (
    <div className="sa-scan-options">
      <div className="sa-scan-options-head">
        <Settings2 size={16} />
        <strong>Perfil de scan nmap</strong>
      </div>

      <div className="sa-scan-profile-grid">
        {PROFILE_ORDER.map((id) => {
          const meta = profiles.find((p) => p.id === id) ?? {
            id,
            label: id === "custom" ? "Personalizado" : id,
            description: "Configure manualmente",
          };
          const active = value.profile === id;
          return (
            <button
              key={id}
              type="button"
              className={`sa-scan-profile-card ${active ? "sa-scan-profile-card-active" : ""}`}
              disabled={disabled}
              onClick={() => selectProfile(id)}
            >
              <span className="sa-scan-profile-title">{meta.label}</span>
              <span className="sa-scan-profile-desc">{meta.description}</span>
            </button>
          );
        })}
      </div>

      <button
        type="button"
        className="sa-scan-advanced-toggle"
        disabled={disabled}
        onClick={() => setAdvancedOpen((o) => !o)}
      >
        {advancedOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        Opções avançadas {isCustom ? "(obrigatório no perfil personalizado)" : ""}
      </button>

      {advancedOpen && (
        <div className="sa-scan-advanced-panel">
          <section>
            <h4>Nmap — descoberta e portas</h4>
            <div className="sa-scan-opt-grid">
              <Toggle
                label="Apenas descoberta (-sn)"
                hint="Sem scan de portas"
                checked={Boolean(value.discover_only)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ discover_only: v, port_scan: !v })}
              />
              <Toggle
                label="Scan de portas"
                checked={value.discover_only ? false : value.port_scan !== false}
                disabled={disabled || !isCustom || Boolean(value.discover_only)}
                onChange={(v) => patch({ port_scan: v, discover_only: !v })}
              />
              <Toggle
                label="Detecção de serviço (-sV)"
                checked={value.service_detection !== false}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ service_detection: v })}
              />
              <Toggle
                label="Detecção de OS (-O)"
                checked={value.os_detection !== false}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ os_detection: v })}
              />
              <Toggle
                label="Scripts NSE (-sC)"
                checked={Boolean(value.script_scan)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ script_scan: v })}
              />
              <Toggle
                label="Scan UDP (top 100)"
                checked={Boolean(value.udp_scan)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ udp_scan: v })}
              />
              <Toggle
                label="Inventariar sub-rede completa"
                hint="Registra todos os IPs (/24): ativos + inativos"
                checked={value.inventory_full_subnet !== false}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ inventory_full_subnet: v })}
              />
              <Toggle
                label="Confirmar com ping ICMP"
                hint="Filtra falsos positivos do nmap (recomendado)"
                checked={value.ping_verify !== false}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ ping_verify: v })}
              />
              <Toggle
                label="Ignorar rede suspeita"
                hint="Força scan mesmo com muitos falsos positivos"
                checked={Boolean(value.skip_suspicious_check)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ skip_suspicious_check: v })}
              />
            </div>

            <div className="sa-scan-opt-row">
              <label className="sa-scan-opt-field">
                <span>Tipo de scan</span>
                <select
                  className="sa-input"
                  value={value.scan_type ?? "syn"}
                  disabled={disabled || !isCustom}
                  onChange={(e) => patch({ scan_type: e.target.value as ScanOptionsPayload["scan_type"] })}
                >
                  {(defaults?.scan_types ?? [{ id: "syn", label: "SYN (-sS)" }]).map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.label}
                    </option>
                  ))}
                </select>
              </label>
              <NumField
                label="Timing (-T0 a -T5)"
                value={value.timing ?? 4}
                min={limits?.timing.min ?? 0}
                max={limits?.timing.max ?? 5}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ timing: v })}
              />
              <NumField
                label="Top portas"
                value={value.top_ports ?? limits?.top_ports.default ?? 500}
                min={limits?.top_ports.min ?? 10}
                max={limits?.top_ports.max ?? 65535}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ top_ports: v, port_range: undefined })}
              />
              <label className="sa-scan-opt-field">
                <span>Portas custom (-p)</span>
                <input
                  className="sa-input"
                  placeholder="22,80,443 ou 1-1024"
                  value={value.port_range ?? ""}
                  disabled={disabled || !isCustom}
                  onChange={(e) => patch({ port_range: e.target.value || undefined, top_ports: undefined })}
                />
              </label>
            </div>
          </section>

          <section>
            <h4>SNMP e inventário</h4>
            <div className="sa-scan-opt-grid">
              <Toggle
                label="Usar SNMP"
                checked={value.use_snmp !== false}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ use_snmp: v })}
              />
              <Toggle
                label="Inventário rápido"
                hint="Pula DNS/RDAP/SNMP profundo"
                checked={Boolean(value.fast_inventory)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ fast_inventory: v })}
              />
              <Toggle
                label="Marcar ausentes como inativos"
                checked={value.mark_missing_inactive !== false}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ mark_missing_inactive: v })}
              />
              <Toggle
                label="Usar WMI (Windows)"
                hint="Requer WMI_ENABLED e credenciais no .env"
                checked={Boolean(value.use_wmi)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ use_wmi: v })}
              />
              <Toggle
                label="Usar SSH (discovery)"
                hint="Requer SSH_ENABLED e credenciais no .env"
                checked={Boolean(value.use_ssh)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ use_ssh: v })}
              />
              <Toggle
                label="Inventário de software"
                hint="SNMP hrSW + WMI (scan mais lento)"
                checked={Boolean(value.collect_software)}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ collect_software: v })}
              />
            </div>
            <div className="sa-scan-opt-row">
              <label className="sa-scan-opt-field">
                <span>Community SNMP</span>
                <input
                  className="sa-input"
                  placeholder="public"
                  value={value.snmp_community ?? ""}
                  disabled={disabled || !isCustom}
                  onChange={(e) => patch({ snmp_community: e.target.value || undefined })}
                />
              </label>
              <NumField
                label="Máx. hosts inventário"
                value={value.max_inventory_hosts ?? limits?.max_inventory_hosts.default ?? 32}
                min={limits?.max_inventory_hosts.min ?? 1}
                max={limits?.max_inventory_hosts.max ?? 512}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ max_inventory_hosts: v })}
              />
              <NumField
                label="Máx. hosts scan detalhado"
                value={value.max_detail_hosts ?? limits?.max_detail_hosts.default ?? 64}
                min={limits?.max_detail_hosts.min ?? 1}
                max={limits?.max_detail_hosts.max ?? 512}
                disabled={disabled || !isCustom}
                onChange={(v) => patch({ max_detail_hosts: v })}
              />
            </div>
          </section>

          <section>
            <h4>Timeouts (segundos)</h4>
            <div className="sa-scan-opt-row">
              <NumField
                label="Descoberta"
                value={value.discover_timeout_seconds ?? 180}
                min={30}
