"""Event bus in-memory para SSE / push de monitoramento."""

from __future__ import annotations

import asyncio
from collections import deque
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any

MAX_EVENTS = 500


@dataclass
class RealtimeEvent:
    type: str
    payload: dict[str, Any] = field(default_factory=dict)
    created_at: str = field(default_factory=lambda: datetime.now(UTC).isoformat())

    def to_dict(self) -> dict[str, Any]:
        return {"type": self.type, "payload": self.payload, "created_at": self.created_at}


class RealtimeEventBus:
    def __init__(self) -> None:
        self._history: deque[RealtimeEvent] = deque(maxlen=MAX_EVENTS)
        self._subscribers: set[asyncio.Queue[RealtimeEvent]] = set()

    def publish(self, event_type: str, payload: dict[str, Any] | None = None) -> None:
        event = RealtimeEvent(type=event_type, payload=payload or {})
        self._history.append(event)
        for queue in list(self._subscribers):
            try:
                queue.put_nowait(event)
            except asyncio.QueueFull:
                pass

    def recent(self, limit: int = 20) -> list[dict[str, Any]]:
        return [e.to_dict() for e in list(self._history)[-limit:]]

    async def subscribe(self) -> asyncio.Queue[RealtimeEvent]:
        queue: asyncio.Queue[RealtimeEvent] = asyncio.Queue(maxsize=64)
        self._subscribers.add(queue)
        return queue

    def unsubscribe(self, queue: asyncio.Queue[RealtimeEvent]) -> None:
        self._subscribers.discard(queue)


event_bus = RealtimeEventBus()
